import {type FieldDefinition} from '@sanity/types'

import {
  SanityAsset,
  SanityAssetCollection,
  SanityAssetVersion,
  SanityVideoAsset,
  SanityFileAsset,
  SanityImageAsset,
  SanityImageIptcMetadata as GeneratedImageIptcMetadata,
  SanityImageIptcXmp as GeneratedImageIptcXmp,
} from './schema.types'

export type {
  SanityVideoAsset,
  SanityAssetUploadSession as UploadSession,
  SanityVideoMetadataRendition,
} from './schema.types'

// XMP text stays as strings; structures and qualified values preserve their source fields.
export type XmpValue = string | XmpObject | Array<string | XmpObject>
export type XmpObject = {[key: string]: XmpValue}

// XMP properties are grouped by namespace prefix alongside the object's _type.
export type SanityImageIptcXmp = GeneratedImageIptcXmp & {
  [namespace: string]: XmpObject | GeneratedImageIptcXmp['_type']
}

export type SanityImageIptcMetadata = Omit<GeneratedImageIptcMetadata, 'xmp'> & {
  xmp?: SanityImageIptcXmp
}

// The schema leaves XMP opaque. Refine it here for consumers of image asset documents.
export type ImageAssetInstanceDocument = Omit<SanityImageAsset, 'metadata'> & {
  metadata: Omit<SanityImageAsset['metadata'], 'iptc'> & {
    iptc?: SanityImageIptcMetadata
  }
}

export interface AssetVersion<AssetInstance extends AssetInstanceDocument = AssetInstanceDocument> {
  _key: string
  _type: SanityAssetVersion['_type']
  title?: string
  instance: AssetInstance
}

export type AssetInstanceDocument = ImageAssetInstanceDocument | SanityVideoAsset | SanityFileAsset

export interface Asset<AssetInstance extends AssetInstanceDocument = AssetInstanceDocument> {
  _id: string
  _originalId?: string
  _type: SanityAsset['_type']
  title: string
  assetType: AssetInstance['_type']
  cdnAccessPolicy: SanityAsset['cdnAccessPolicy']
  currentVersion: {
    _ref: string
  }
  aspects?: unknown
  versions: AssetVersion<AssetInstance>[]
  collections: SanityAssetCollection[]
  _createdAt: string
  _updatedAt: string
  _rev: string
  url?: string
}

export type BaseDocument = {
  _id: string
  _type: string
  _rev: string
  _createdAt: string
  _updatedAt: string
  [key: string]: any
}

export interface AssetAspectDocument extends BaseDocument {
  _type: 'sanity.asset.aspect'
  /**
   * The asset type this aspect definition applies to
   * Undefined means that it applies to all asset types
   */
  assetType?: Asset['assetType']
  definition: FieldDefinition
  public?: boolean
}
